/* Storelib: every database change since round 41, in one paste for the Supabase SQL editor.
   Parts in this order: 329, 331, 333, 334, 338, 341, 342, 343, 344, 345, 346, 347, 348, 349, 350, 352, 354, 355, 356, 360, 363, 366, 353. Text exactly as in supabase/sql/run-now/; 353 runs last so the policies the parts before it make get its rewrite in the same paste.
   Every part is safe to run again: one that already ran changes nothing.
   Part 343 builds four indexes; on a very large products table, run supabase/sql/RUN_SITEMAP_INDEXES_CONCURRENTLY.sql first (one line per Run), and this file then finds them made.
   The last row is one column per part, each true once it has run. */

-- 329_store_credit_notes.sql
/* Credit notes for refunds, in the store's invoice sequence (round cn-1028, run after part 321): every refund, full or partial, made from the Orders page, the Stripe dashboard or the admin, gets one credit note that names the invoice it corrects and the lines and tax it gives back, numbered from the same per store counter as invoices (store_invoice_series), so an accountant reads 000153 Invoice, 000154 Credit note, 000155 Invoice. New store_credit_notes (one row per refund: the purchase's first order, the refund it is for, its number, amount, currency and how the refund was split over the order's lines; unique per store and refund, and per store and number), server only (row level security on, no policy, nothing granted to anon or signed in users), and public.storelib_credit_note(store, order, refund, amount, currency, shares), for the service role only, which hands out the store's next number under the same lock on the store's row as invoices and gives the same note every time after for that refund, so a webhook retried or a refund seen from two places is credited once. Until it runs refunds are recorded as before, with no credit note. Safe to run again. */
create table if not exists public.store_credit_notes (id uuid primary key default gen_random_uuid(), creator_id uuid not null, order_id uuid not null, refund_key text not null check (length(refund_key) between 1 and 200), seq integer not null check (seq > 0), amount_cents integer not null check (amount_cents > 0), currency text not null check (currency ~ '^[A-Za-z]{3}$'), shares jsonb not null default '[]'::jsonb, issued_at timestamptz not null default now(), constraint store_credit_notes_refund_key unique (creator_id, refund_key), constraint store_credit_notes_creator_seq_key unique (creator_id, seq));
create index if not exists store_credit_notes_order on public.store_credit_notes (order_id, issued_at);
create table if not exists public.store_invoice_series (creator_id uuid primary key, last_seq integer not null default 0 check (last_seq >= 0), updated_at timestamptz not null default now());
alter table public.store_credit_notes enable row level security;
alter table public.store_invoice_series enable row level security;
revoke all on public.store_credit_notes from anon, authenticated;
revoke all on public.store_invoice_series from anon, authenticated;
create or replace function public.storelib_credit_note(p_creator uuid, p_order uuid, p_refund text, p_amount integer, p_currency text, p_shares jsonb) returns jsonb language plpgsql security definer set search_path = public as $f$ declare v_row public.store_credit_notes%rowtype; v_seq integer; begin if p_creator is null or p_order is null or p_refund is null or length(p_refund) = 0 or p_amount is null or p_amount <= 0 or p_currency is null then return null; end if; select * into v_row from public.store_credit_notes n where n.creator_id = p_creator and n.refund_key = p_refund; if v_row.id is not null then return to_jsonb(v_row); end if; perform 1 from public.orders o join public.products p on p.id = o.product_id where o.id = p_order and p.creator_id = p_creator; if not found then return null; end if; insert into public.store_invoice_series (creator_id) values (p_creator) on conflict (creator_id) do nothing; perform 1 from public.store_invoice_series s where s.creator_id = p_creator for update; select * into v_row from public.store_credit_notes n where n.creator_id = p_creator and n.refund_key = p_refund; if v_row.id is not null then return to_jsonb(v_row); end if; update public.store_invoice_series s set last_seq = s.last_seq + 1, updated_at = now() where s.creator_id = p_creator returning s.last_seq into v_seq; insert into public.store_credit_notes (creator_id, order_id, refund_key, seq, amount_cents, currency, shares) values (p_creator, p_order, p_refund, v_seq, p_amount, upper(p_currency), case when jsonb_typeof(p_shares) = 'array' then p_shares else '[]'::jsonb end) returning * into v_row; return to_jsonb(v_row); end $f$;
revoke all on function public.storelib_credit_note(uuid, uuid, text, integer, text, jsonb) from public, anon, authenticated;
grant execute on function public.storelib_credit_note(uuid, uuid, text, integer, text, jsonb) to service_role;
notify pgrst, 'reload schema';

-- 331_analytics_clicks_between_pages_and_row_lines.sql
/* Analytics: clicks between pages, and each row's own line (round ana-1028b, run after part 61). A link or a button on a website that leads to another page of the same site is recorded as a `nav_click` event (the event type check allows it; `analytics_events.link_label`, at most 80 characters, keeps the button's words; `path` is the page it was on and `link_url` the page it led to) and `analytics_nav_clicks` counts them for the Clicks report (both periods, the 100 most clicked buttons, with the people who clicked), with a partial index on `analytics_events (creator_id, created_at) WHERE event_type = 'nav_click'`. `analytics_row_series` counts one report's rows over the chart's buckets for an opened report (a page's views, a link's or a button's clicks, a source's, referrer's, campaign's, device's, country's or browser's visits, where each visit began), the 100 busiest rows. Both are server only (service role). No existing row changes. Until it runs, internal clicks are not recorded and an opened report's rows are counted from the events by the app. Safe to run again. */
ALTER TABLE public.analytics_events ADD COLUMN IF NOT EXISTS link_label text;
ALTER TABLE public.analytics_events DROP CONSTRAINT IF EXISTS analytics_events_link_label_check;
ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_link_label_check CHECK (link_label IS NULL OR char_length(link_label) <= 80) NOT VALID;
ALTER TABLE public.analytics_events DROP CONSTRAINT IF EXISTS analytics_events_event_type_check;
ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_event_type_check CHECK (event_type IN ('view', 'purchase', 'session_start', 'store_view', 'product_view', 'add_to_cart', 'checkout_start', 'buy_click', 'checkout_complete', 'download', 'link_click', 'nav_click')) NOT VALID;
CREATE INDEX IF NOT EXISTS idx_analytics_events_nav_click_time ON public.analytics_events (creator_id, created_at) WHERE event_type = 'nav_click';
CREATE OR REPLACE FUNCTION public.analytics_nav_clicks(p_creator_id uuid, p_property_type text, p_property_id uuid, p_default_website uuid, p_cur_start timestamptz, p_cur_end timestamptz, p_prev_start timestamptz DEFAULT NULL, p_prev_end timestamptz DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path = public AS $fn$ DECLARE v_pred text := ''; v_out jsonb; v_ps timestamptz := coalesce(p_prev_start, p_cur_start); v_pe timestamptz := greatest(coalesce(p_prev_start, p_cur_start), coalesce(p_prev_end, p_cur_start)); BEGIN IF p_creator_id IS NULL OR p_cur_start IS NULL OR p_cur_end IS NULL OR p_cur_end <= p_cur_start THEN RAISE EXCEPTION 'analytics_nav_clicks: a creator and a period are needed'; END IF; IF p_property_type IS NOT NULL AND p_property_type NOT IN ('creator_page', 'onepage', 'website') THEN RAISE EXCEPTION 'analytics_nav_clicks: unknown property type %', p_property_type; END IF; /* The property is a condition of its own, so each read is planned for what it is asked; a website row that never knew its install is the live website's. */ IF p_property_type IS NOT NULL THEN v_pred := ' AND e.property_type = $2'; IF p_property_type = 'website' AND p_property_id IS NOT NULL THEN v_pred := v_pred || CASE WHEN p_property_id = p_default_website THEN ' AND (e.property_id = $3 OR e.property_id IS NULL)' ELSE ' AND e.property_id = $3' END; END IF; END IF; EXECUTE format($q$ WITH ev AS ( SELECT e.id, e.created_at, e.property_type AS pt, e.property_id AS pid, e.path, e.link_url, e.link_label, coalesce(nullif(e.visitor_id::text, ''), nullif(e.session_id::text, ''), 'e:' || e.id::text) AS who, (e.created_at >= $4 AND e.created_at < $5) AS now_ FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'nav_click' AND e.property_type IS NOT NULL %s AND ((e.created_at >= $4 AND e.created_at < $5) OR (e.created_at >= $6 AND e.created_at < $7)) ), cur AS (SELECT * FROM ev WHERE now_), prev AS (SELECT * FROM ev WHERE NOT now_ AND created_at >= $6 AND created_at < $7), grouped AS ( SELECT c.pt, c.pid, c.path, c.link_url, c.link_label, count(*)::int AS clicks, count(DISTINCT c.who)::int AS people, (coalesce(c.pt, '') || '|' || coalesce(c.pid::text, '') || '|' || coalesce(c.path, '') || '|' || coalesce(c.link_url, '') || '|' || coalesce(c.link_label, '')) COLLATE "C" AS k FROM cur c GROUP BY c.pt, c.pid, c.path, c.link_url, c.link_label ), top AS (SELECT * FROM grouped ORDER BY clicks DESC, k LIMIT 100) SELECT jsonb_build_object( 'cur', (SELECT count(*) FROM cur), 'prev', (SELECT count(*) FROM prev), 'rows', coalesce((SELECT jsonb_agg(jsonb_build_array(t.pt, t.pid, t.path, t.link_url, t.link_label, t.clicks, t.people, (SELECT count(*) FROM prev p WHERE p.pt = t.pt AND p.pid IS NOT DISTINCT FROM t.pid AND p.path IS NOT DISTINCT FROM t.path AND p.link_url IS NOT DISTINCT FROM t.link_url AND p.link_label IS NOT DISTINCT FROM t.link_label)) ORDER BY t.clicks DESC, t.k) FROM top t), '[]'::jsonb)) $q$, v_pred) INTO v_out USING p_creator_id, p_property_type, p_property_id, p_cur_start, p_cur_end, v_ps, v_pe; RETURN v_out; END; $fn$;
REVOKE ALL ON FUNCTION public.analytics_nav_clicks(uuid, text, uuid, uuid, timestamptz, timestamptz, timestamptz, timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_nav_clicks(uuid, text, uuid, uuid, timestamptz, timestamptz, timestamptz, timestamptz) TO service_role;
CREATE OR REPLACE FUNCTION public.analytics_row_series(p_creator_id uuid, p_property_type text, p_property_id uuid, p_default_website uuid, p_product_id uuid, p_start timestamptz, p_end timestamptz, p_starts timestamptz[], p_dim text) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path = public SET work_mem = '64MB' AS $fn$ DECLARE v_pred text := ''; v_n integer := coalesce(cardinality(p_starts), 0); v_rows text; v_out jsonb; BEGIN IF p_creator_id IS NULL OR p_start IS NULL OR p_end IS NULL OR p_end <= p_start THEN RAISE EXCEPTION 'analytics_row_series: a creator and a period are needed'; END IF; IF p_dim IS NULL OR p_dim NOT IN ('page', 'link', 'nav', 'source', 'referrer', 'campaign', 'device', 'country', 'browser') THEN RAISE EXCEPTION 'analytics_row_series: unknown dimension %', p_dim; END IF; IF p_property_type IS NOT NULL AND p_property_type NOT IN ('creator_page', 'onepage', 'website') THEN RAISE EXCEPTION 'analytics_row_series: unknown property type %', p_property_type; END IF; IF v_n = 0 OR v_n > 1000 THEN RETURN '{}'::jsonb; END IF; /* A click is not of a product: with a product chosen there are none (lib/analytics/reports wireFromRows). */ IF p_product_id IS NOT NULL AND p_dim IN ('link', 'nav') THEN RETURN '{}'::jsonb; END IF; IF p_property_type IS NOT NULL THEN v_pred := ' AND e.property_type = $2'; IF p_property_type = 'website' AND p_property_id IS NOT NULL THEN v_pred := v_pred || CASE WHEN p_property_id = p_default_website THEN ' AND (e.property_id = $3 OR e.property_id IS NULL)' ELSE ' AND e.property_id = $3' END; END IF; END IF; IF p_product_id IS NOT NULL THEN v_pred := v_pred || ' AND e.product_id = $4'; END IF; /* The rows: (key, moment) for each counted thing. A page's views and a link's or a button's clicks where they happened; a breakdown's visits where each began (its first page, or the first after more than the previous UTC day without one), on its 15 minute slot, keyed by that first page, as analytics_property_counts keys them. */ v_rows := CASE p_dim WHEN 'page' THEN format($r$SELECT (e.property_type || '|' || coalesce(e.property_id::text, '') || '|' || coalesce(e.path, '')) AS k, e.created_at AS at FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'view' AND e.property_type IS NOT NULL AND e.created_at >= $5 AND e.created_at < $6 %s$r$, v_pred) WHEN 'link' THEN format($r$SELECT (e.property_type || '|' || coalesce(e.property_id::text, '') || '|' || coalesce(nullif(e.link_id, ''), nullif(e.link_url, ''), '')) AS k, e.created_at AS at FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'link_click' AND e.property_type IS NOT NULL AND e.created_at >= $5 AND e.created_at < $6 %s$r$, v_pred) WHEN 'nav' THEN format($r$SELECT (e.property_type || '|' || coalesce(e.property_id::text, '') || '|' || coalesce(e.path, '') || '|' || coalesce(e.link_url, '') || '|' || coalesce(e.link_label, '')) AS k, e.created_at AS at FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'nav_click' AND e.property_type IS NOT NULL AND e.created_at >= $5 AND e.created_at < $6 %s$r$, v_pred) ELSE format($r$SELECT s.k, to_timestamp(floor(extract(epoch FROM s.created_at) / 900) * 900) AS at FROM ( SELECT v.created_at, v.k, lag(v.created_at) OVER (PARTITION BY v.pk, v.skey ORDER BY v.created_at, v.id) AS before FROM (SELECT e.id, e.created_at, e.property_type || ':' || coalesce(e.property_id::text, '') AS pk, (CASE WHEN coalesce(e.session_id::text, '') <> '' THEN e.session_id::text WHEN coalesce(e.visitor_id::text, '') <> '' THEN 'v:' || e.visitor_id::text || ':' || to_char(e.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD') ELSE 'e:' || e.id::text END) COLLATE "C" AS skey, %s AS k FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'view' AND e.property_type IS NOT NULL AND e.created_at >= $5 - interval '1 day' AND e.created_at < $6 %s) v ) s WHERE s.created_at >= $5 AND s.k IS NOT NULL AND (s.before IS NULL OR s.before < (((s.created_at AT TIME ZONE 'UTC')::date - 1)::timestamp AT TIME ZONE 'UTC'))$r$, CASE p_dim WHEN 'source' THEN $k$coalesce(nullif(e.source_category, ''), 'direct')$k$ WHEN 'referrer' THEN $k$coalesce(nullif(lower(regexp_replace(coalesce(e.referrer_domain, ''), '^www\.', '')), ''), 'direct')$k$ WHEN 'campaign' THEN $k$nullif(e.utm_campaign, '')$k$ WHEN 'device' THEN $k$coalesce(nullif(lower(e.device_type), ''), 'unknown')$k$ WHEN 'country' THEN $k$coalesce(nullif(upper(e.country_code), ''), 'unknown')$k$ ELSE $k$coalesce(nullif(lower(e.browser), ''), 'unknown')$k$ END, v_pred) END; EXECUTE format($q$ WITH r AS (%s), b AS (SELECT r.k COLLATE "C" AS k, width_bucket(r.at, $7) - 1 AS i, count(*)::int AS n FROM r GROUP BY 1, 2), kept AS (SELECT b.k, b.i, b.n FROM b WHERE b.i >= 0 AND b.i < $8), top AS (SELECT kept.k, sum(kept.n) AS total FROM kept GROUP BY kept.k ORDER BY sum(kept.n) DESC, kept.k LIMIT 100) SELECT coalesce(jsonb_object_agg(t.k, (SELECT jsonb_agg(coalesce(x.n, 0) ORDER BY g.i) FROM generate_series(0, $8 - 1) g(i) LEFT JOIN kept x ON x.k = t.k AND x.i = g.i)), '{}'::jsonb) FROM top t $q$, v_rows) INTO v_out USING p_creator_id, p_property_type, p_property_id, p_product_id, p_start, p_end, p_starts, v_n; RETURN v_out; END; $fn$;
REVOKE ALL ON FUNCTION public.analytics_row_series(uuid, text, uuid, uuid, uuid, timestamptz, timestamptz, timestamptz[], text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_row_series(uuid, text, uuid, uuid, uuid, timestamptz, timestamptz, timestamptz[], text) TO service_role;
notify pgrst, 'reload schema';

-- 333_team_money_areas.sql
/* The website, the creator page, payouts and billing for the team (round 42, run after parts 319 and 320): the four parts of a store still closed to a team member open, and money is given in two steps each. A member's permissions (store_team_members.permissions) may now also hold payouts (see the balance and payouts), payouts_manage (cash out and change the payout bank), billing (see the plan and invoices) and billing_manage (change the plan and the card); the old payouts_billing key stays allowed, so no row stops being valid, and the app no longer gives it. The check on the column is replaced with one that knows the new keys, and public.team_store_ids answers for them too. Nothing is written to any row, no policy is added and nothing changes for the owner or for visitors: the website and the creator page are read and written by the server with the member's permissions checked on each request (lib/team/website, lib/team/creator-page), and payouts and billing are server only (lib/team/money). The table stays server only. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_team_members') IS NULL THEN RAISE NOTICE 'part 333: store_team_members is not here yet; run part 135, then 319 and 320, then this again.'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'store_team_members' AND column_name = 'permissions') THEN RAISE NOTICE 'part 333: store_team_members.permissions is not here yet; run part 320 first, then this again.'; RETURN; END IF; ALTER TABLE public.store_team_members DROP CONSTRAINT IF EXISTS store_team_members_permissions_check; ALTER TABLE public.store_team_members ADD CONSTRAINT store_team_members_permissions_check CHECK (permissions IS NULL OR (permissions <@ ARRAY['website', 'onepage', 'creator_pages', 'products', 'orders', 'customers', 'marketing', 'community', 'analytics', 'settings', 'team', 'payouts', 'payouts_manage', 'billing', 'billing_manage', 'payouts_billing']::text[] AND cardinality(permissions) <= 16)); COMMENT ON COLUMN public.store_team_members.permissions IS 'What this member may do in the store (lib/team/permissions.ts). payouts_manage and billing_manage always come with payouts and billing (part 333). NULL: read as the role (manager: orders).'; IF to_regprocedure('public.team_store_ids(text)') IS NOT NULL THEN EXECUTE $f$create or replace function public.team_store_ids(p_area text) returns setof uuid language sql stable security definer set search_path = public as $b$ select m.creator_id from public.store_team_members m where (select auth.uid()) is not null and m.user_id = (select auth.uid()) and m.status = 'active' and p_area = any (array['website', 'onepage', 'creator_pages', 'products', 'orders', 'customers', 'marketing', 'community', 'analytics', 'settings', 'team', 'payouts', 'payouts_manage', 'billing', 'billing_manage']) and coalesce(to_jsonb(m) -> 'permissions', '[]'::jsonb) ? p_area $b$$f$; REVOKE ALL ON FUNCTION public.team_store_ids(text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.team_store_ids(text) TO authenticated, service_role; ELSE RAISE NOTICE 'part 333: public.team_store_ids is not here yet; run part 319, then this again for it.'; END IF; END $do$;
notify pgrst, 'reload schema';

-- 334_database_load_and_isolation.sql
/* Database load and store isolation (round rel-db). Indexes for reads and deletes that searched a whole table: the Emails page's activity (commerce_order_events by store and kind, email_flow_sends by store and status), a sale's attribution and the shop page builder (onepages by creator_id and seller_id), a community's messages by community and time (orphaned uploads, a community deleted), the reply link on chat messages (deleting one message searched every message for replies to it, so deleting a space or a community took time in the square of its messages), a subscriber's campaign and email recipients (an account deleted unlinked each subscriber with a search of both tables), and the links a product, an order, a variant or a space leaves behind when it is deleted. Then store isolation: functions that run with their owner's rights and take any store's id (raise sales and view counts, write a customer into any store's list, read a store's email or OnePage figures, set up a store's themes) or rebuild whole tables (the rollups, the partition swap) are closed to the public key and signed in accounts; the server calls every one with the service role, as before. Policies that let any signed in account read and change every store's customers, or anybody read every verification code and security event, or write notifications into any seller's bell, are dropped; each owner's own policies stay. The public key now reads only a digital file's id, product, name and date (what a product page lists), and a signed in account reads only its own store's files and the ones it bought, no longer every store's. The unused partitioned copies of the analytics tables get row level security and lose public access, and the indexability view is the server's. Last, a statement timeout for the API roles where none is set (anon 3s and authenticated 8s as Supabase sets them, service_role 120s, past the app's own 60s limit on a request), so a query nobody waits for any more stops. No row changes. LOCKS: a plain CREATE INDEX stops writes to its table while it builds and the editor holds that to the end of the paste: on a large database run supabase/sql/RUN_REL_DB_INDEXES_CONCURRENTLY.sql first, line by line, and this part then finds every index made. Each index is made only when its table and columns are there. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.commerce_order_events') IS NULL THEN RAISE NOTICE 'part 334: commerce_order_events_creator_kind_idx skipped, public.commerce_order_events does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'commerce_order_events' AND column_name = 'creator_id') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'commerce_order_events' AND column_name = 'kind') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'commerce_order_events' AND column_name = 'created_at') THEN RAISE NOTICE 'part 334: commerce_order_events_creator_kind_idx skipped, public.commerce_order_events lacks a column it needs'; RETURN; END IF; IF to_regclass('public.commerce_order_events_creator_kind_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS commerce_order_events_creator_kind_idx ON public.commerce_order_events (creator_id, kind, created_at); END $do$;
DO $do$ BEGIN IF to_regclass('public.email_flow_sends') IS NULL THEN RAISE NOTICE 'part 334: email_flow_sends_creator_status_idx skipped, public.email_flow_sends does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'email_flow_sends' AND column_name = 'creator_id') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'email_flow_sends' AND column_name = 'status') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'email_flow_sends' AND column_name = 'sent_at') THEN RAISE NOTICE 'part 334: email_flow_sends_creator_status_idx skipped, public.email_flow_sends lacks a column it needs'; RETURN; END IF; IF to_regclass('public.email_flow_sends_creator_status_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS email_flow_sends_creator_status_idx ON public.email_flow_sends (creator_id, status, sent_at); END $do$;
DO $do$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'part 334: onepages_creator_idx skipped, public.onepages does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'onepages' AND column_name = 'creator_id') THEN RAISE NOTICE 'part 334: onepages_creator_idx skipped, public.onepages lacks a column it needs'; RETURN; END IF; IF to_regclass('public.onepages_creator_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS onepages_creator_idx ON public.onepages (creator_id) WHERE creator_id IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'part 334: onepages_seller_idx skipped, public.onepages does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'onepages' AND column_name = 'seller_id') THEN RAISE NOTICE 'part 334: onepages_seller_idx skipped, public.onepages lacks a column it needs'; RETURN; END IF; IF to_regclass('public.onepages_seller_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS onepages_seller_idx ON public.onepages (seller_id) WHERE seller_id IS NOT NULL; END $do$;
