DO $do$ DECLARE t regclass; BEGIN FOR t IN SELECT c.oid::regclass FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname IN ('analytics_events_partitioned', 'onepage_views_partitioned') UNION SELECT i.inhrelid::regclass FROM pg_inherits i JOIN pg_class p ON p.oid = i.inhparent JOIN pg_namespace n ON n.oid = p.relnamespace WHERE n.nspname = 'public' AND p.relname IN ('analytics_events_partitioned', 'onepage_views_partitioned', 'analytics_events', 'onepage_views') LOOP EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', t); EXECUTE format('REVOKE ALL ON %s FROM anon, authenticated', t); END LOOP; END $do$;
DO $do$ DECLARE r record; BEGIN FOR r IN SELECT * FROM (VALUES ('anon', '3s'), ('authenticated', '8s'), ('service_role', '120s')) AS v(role, wait) LOOP IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r.role) THEN CONTINUE; END IF; IF EXISTS (SELECT 1 FROM pg_db_role_setting s JOIN pg_roles o ON o.oid = s.setrole WHERE o.rolname = r.role AND s.setdatabase = 0 AND EXISTS (SELECT 1 FROM unnest(s.setconfig) AS c WHERE c LIKE 'statement_timeout=%')) THEN CONTINUE; END IF; BEGIN EXECUTE format('ALTER ROLE %I SET statement_timeout = %L', r.role, r.wait); EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'part 334: statement_timeout for % not set here (this role may not change it); set it in Database > Roles or ask support', r.role; END; END LOOP; END $do$;
