-- 338_analytics_destinations.sql
/* Storelib analytics sent on to a store's other tools, and read by them (round ana-1029): new `analytics_destinations`, one row per store and tool (Google Analytics 4 by the Measurement Protocol, Meta's Conversions API, PostHog, or a signed webhook of the store's own), holding the tool's ids (`config`: a measurement id, a pixel id, a host) and its API secret, access token, project key or webhook address and signing secret sealed by the server (`secret_ciphertext`, AES-256-GCM, never readable by a browser); new `analytics_forward_jobs`, the queue and the delivery log: one row per tool and event (`event_key`, unique per tool, so a purchase told twice is sent once), the event's facts (`facts`, no person in them), what consent allowed about the person (`person`, emptied once the row is done), its state (queued, sending, sent, failed, skipped), the tries and when the next one is due, the tool's answer code and its error; new `analytics_api_tokens`, read only keys for GET /api/v1/analytics, kept as a SHA-256 of the key and its first characters (the key itself is shown once), revocable (`revoked_at`). Written and read only by the server (lib/analytics/destinations): row level security on, nothing granted to anon or authenticated. New tables only; no existing row changes. Until it runs, Analytics › Send to says this part is needed and nothing is sent. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.analytics_destinations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL CHECK (provider IN ('ga4', 'meta', 'posthog', 'webhook')), status text NOT NULL DEFAULT 'connected' CHECK (status IN ('connected', 'paused')), account_label text CHECK (account_label IS NULL OR length(account_label) <= 200), config jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(config) = 'object'), secret_ciphertext text CHECK (secret_ciphertext IS NULL OR secret_ciphertext LIKE 'v1.%'), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT analytics_destinations_one_per_tool UNIQUE (creator_id, provider));
CREATE INDEX IF NOT EXISTS analytics_destinations_connected_idx ON public.analytics_destinations (creator_id) WHERE status = 'connected';
ALTER TABLE public.analytics_destinations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.analytics_destinations FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.analytics_destinations TO service_role;
CREATE TABLE IF NOT EXISTS public.analytics_forward_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), destination_id uuid NOT NULL REFERENCES public.analytics_destinations(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, event_name text NOT NULL CHECK (event_name IN ('page_view', 'view_item', 'purchase', 'refund', 'lead', 'sign_up', 'test')), event_key text NOT NULL CHECK (length(event_key) BETWEEN 1 AND 200), subject_ref text CHECK (subject_ref IS NULL OR length(subject_ref) <= 100), facts jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(facts) = 'object'), person jsonb CHECK (person IS NULL OR jsonb_typeof(person) = 'object'), status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'sending', 'sent', 'failed', 'skipped')), attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0), next_attempt_at timestamptz NOT NULL DEFAULT now(), locked_until timestamptz, response_status integer, last_error text CHECK (last_error IS NULL OR length(last_error) <= 500), sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT analytics_forward_jobs_once UNIQUE (destination_id, event_key));
CREATE INDEX IF NOT EXISTS analytics_forward_jobs_due_idx ON public.analytics_forward_jobs (next_attempt_at) WHERE status IN ('queued', 'sending');
CREATE INDEX IF NOT EXISTS analytics_forward_jobs_log_idx ON public.analytics_forward_jobs (destination_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS analytics_forward_jobs_ref_idx ON public.analytics_forward_jobs (creator_id, subject_ref) WHERE status = 'queued';
ALTER TABLE public.analytics_forward_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.analytics_forward_jobs FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.analytics_forward_jobs TO service_role;
CREATE TABLE IF NOT EXISTS public.analytics_api_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, name text NOT NULL CHECK (length(name) BETWEEN 1 AND 80), token_hash text NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'), token_prefix text NOT NULL CHECK (length(token_prefix) <= 20), created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz, revoked_at timestamptz);
CREATE INDEX IF NOT EXISTS analytics_api_tokens_creator_idx ON public.analytics_api_tokens (creator_id, created_at DESC);
ALTER TABLE public.analytics_api_tokens ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.analytics_api_tokens FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.analytics_api_tokens TO service_role;
notify pgrst, 'reload schema';

-- 341_connected_email_platforms.sql
/* Connected email platforms and the store's own sending domain (Emails > Platforms, run after 166). Brevo, MailerLite and Kit join Klaviyo and Omnisend on the marketing sync: the commerce_integrations provider check and the marketing_sync_items provider check are rebuilt with every value they already allow plus brevo, mailerlite and kit (read from the database, so a part that added its own keeps them; a check that is already a pattern, part 163, is left as it is). email_sending_domains keeps one domain per store, added to Storelib's Mailgun account: its SPF, DKIM, tracking and DMARC records with what the last check found, pending until Mailgun says it is active, then verified and used as From on campaigns, automations and the emails buyers get. A domain belongs to one store only. Server only (the service role); nobody reads it with a browser key. No rows change. Safe to run again. */
DO $do$ DECLARE v text[]; BEGIN IF to_regclass('public.commerce_integrations') IS NULL THEN RAISE NOTICE 'commerce_integrations is not there yet: run part 78 first'; RETURN; END IF; IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.commerce_integrations'::regclass AND conname = 'commerce_integrations_provider_check' AND pg_get_constraintdef(oid) LIKE '%~%') THEN RAISE NOTICE 'commerce_integrations_provider_check is a pattern (part 163), which already lets every name in: left as it is'; RETURN; END IF; SELECT coalesce(array_agg(DISTINCT m[1]), '{}'::text[]) INTO v FROM pg_constraint c CROSS JOIN LATERAL regexp_matches(pg_get_constraintdef(c.oid), '[''{,]([a-z][a-z0-9_]*)(?=['',}])', 'g') AS m WHERE c.conrelid = 'public.commerce_integrations'::regclass AND c.conname = 'commerce_integrations_provider_check'; v := ARRAY(SELECT DISTINCT x FROM unnest(v || ARRAY['manual', 'supplier_email', 'custom_webhook', 'csv', 'printful', 'printify', 'gelato', 'cj_dropshipping', 'shipstation', 'shippo', 'easypost', 'klaviyo', 'omnisend', 'brevo', 'mailerlite', 'kit']) AS x ORDER BY x); ALTER TABLE public.commerce_integrations DROP CONSTRAINT IF EXISTS commerce_integrations_provider_check; EXECUTE format('ALTER TABLE public.commerce_integrations ADD CONSTRAINT commerce_integrations_provider_check CHECK (provider = ANY (%L::text[])) NOT VALID', v); END $do$;
DO $do$ DECLARE v text[]; BEGIN IF to_regclass('public.marketing_sync_items') IS NULL THEN RAISE NOTICE 'marketing_sync_items is not there yet: run part 166 first'; RETURN; END IF; SELECT coalesce(array_agg(DISTINCT m[1]), '{}'::text[]) INTO v FROM pg_constraint c CROSS JOIN LATERAL regexp_matches(pg_get_constraintdef(c.oid), '[''{,]([a-z][a-z0-9_]*)(?=['',}])', 'g') AS m WHERE c.conrelid = 'public.marketing_sync_items'::regclass AND c.conname = 'marketing_sync_items_provider_check'; v := ARRAY(SELECT DISTINCT x FROM unnest(v || ARRAY['klaviyo', 'omnisend', 'brevo', 'mailerlite', 'kit']) AS x ORDER BY x); ALTER TABLE public.marketing_sync_items DROP CONSTRAINT IF EXISTS marketing_sync_items_provider_check; EXECUTE format('ALTER TABLE public.marketing_sync_items ADD CONSTRAINT marketing_sync_items_provider_check CHECK (provider = ANY (%L::text[])) NOT VALID', v); END $do$;
CREATE TABLE IF NOT EXISTS public.email_sending_domains (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL UNIQUE REFERENCES public.creators(id) ON DELETE CASCADE, domain text NOT NULL CHECK (char_length(domain) BETWEEN 4 AND 253 AND domain = lower(domain) AND domain ~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$'), from_local text NOT NULL DEFAULT 'hello' CHECK (from_local ~ '^[a-z0-9]([a-z0-9._+-]{0,62}[a-z0-9])?$'), provider text NOT NULL DEFAULT 'mailgun' CHECK (provider IN ('mailgun')), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'verified', 'failed')), records jsonb NOT NULL DEFAULT '[]'::jsonb, last_checked_at timestamptz, verified_at timestamptz, last_error text CHECK (last_error IS NULL OR char_length(last_error) <= 500), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS email_sending_domains_domain_key ON public.email_sending_domains (domain);
ALTER TABLE public.email_sending_domains ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.email_sending_domains FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.email_sending_domains TO service_role;
notify pgrst, 'reload schema';

-- 342_seo_index_status.sql
/* SEO status in /admin/seo (round 44). seo_index_status keeps one row per address Storelib's sitemaps list: its kind, the sitemap file it came from, the Search Console property it belongs to (none for a creator's own domain), whether it is in the sitemap now, Google's answer from the URL Inspection API (verdict, coverage, indexing, robots.txt, fetch, last crawl, Google's canonical and the page's own, when it was asked) and the page's SEO score with each check that made it. seo_inspection_quota counts the inspections spent per property, per Pacific day and per minute, and seo_take_inspection_quota takes from it in one locked step so two runs cannot both spend the last of it. seo_sync_state is where the cron is in its walk through the sitemap files. seo_index_totals adds up each kind for the console. Service role only. No rows change. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.seo_index_status (url text PRIMARY KEY CHECK (char_length(url) BETWEEN 8 AND 2048 AND url ~ '^https?://'), kind text NOT NULL CHECK (kind IN ('page', 'blog', 'help', 'legal', 'profile', 'product', 'collection', 'onepage', 'community', 'website')), source text NOT NULL CHECK (char_length(source) BETWEEN 1 AND 200), property text CHECK (property IS NULL OR char_length(property) BETWEEN 3 AND 300), in_sitemap boolean NOT NULL DEFAULT true, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), left_sitemap_at timestamptz, google_status text CHECK (google_status IN ('indexed', 'not_indexed', 'unknown', 'error', 'no_property')), verdict text, coverage_state text, indexing_state text, robots_txt_state text, page_fetch_state text, last_crawl_time timestamptz, google_canonical text, user_canonical text, inspection_link text, inspect_error text, inspected_at timestamptz, score smallint CHECK (score IS NULL OR score BETWEEN 0 AND 100), checks jsonb, http_status smallint, score_error text, scored_at timestamptz, expanded_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS seo_index_status_kind_idx ON public.seo_index_status (kind, url);
CREATE INDEX IF NOT EXISTS seo_index_status_source_idx ON public.seo_index_status (source) WHERE in_sitemap;
CREATE INDEX IF NOT EXISTS seo_index_status_inspect_next_idx ON public.seo_index_status (property, inspected_at ASC NULLS FIRST, url) WHERE in_sitemap AND property IS NOT NULL;
CREATE INDEX IF NOT EXISTS seo_index_status_score_next_idx ON public.seo_index_status (scored_at ASC NULLS FIRST, url) WHERE in_sitemap;
CREATE INDEX IF NOT EXISTS seo_index_status_google_idx ON public.seo_index_status (google_status, url);
CREATE INDEX IF NOT EXISTS seo_index_status_expand_idx ON public.seo_index_status (expanded_at ASC NULLS FIRST, url) WHERE in_sitemap AND source LIKE 'websites-%';
DO $do$ DECLARE sch text; BEGIN SELECT n.nspname INTO sch FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'pg_trgm'; IF sch IS NULL AND EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_trgm') THEN IF to_regnamespace('extensions') IS NOT NULL THEN CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA extensions; sch := 'extensions'; ELSE CREATE EXTENSION IF NOT EXISTS pg_trgm; SELECT n.nspname INTO sch FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'pg_trgm'; END IF; END IF; IF sch IS NULL THEN RAISE NOTICE 'pg_trgm is not available: searching addresses in /admin/seo works, without an index'; RETURN; END IF; EXECUTE format('CREATE INDEX IF NOT EXISTS seo_index_status_url_trgm_idx ON public.seo_index_status USING gin (url %I.gin_trgm_ops)', sch); END $do$;
ALTER TABLE public.seo_index_status ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.seo_index_status FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.seo_index_status TO service_role;
CREATE TABLE IF NOT EXISTS public.seo_inspection_quota (property text NOT NULL CHECK (char_length(property) BETWEEN 3 AND 300), window_kind text NOT NULL CHECK (window_kind IN ('day', 'minute')), window_start timestamptz NOT NULL, used integer NOT NULL DEFAULT 0 CHECK (used >= 0), PRIMARY KEY (property, window_kind, window_start));
ALTER TABLE public.seo_inspection_quota ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.seo_inspection_quota FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.seo_inspection_quota TO service_role;
CREATE TABLE IF NOT EXISTS public.seo_sync_state (id smallint PRIMARY KEY DEFAULT 1 CHECK (id = 1), files text[] NOT NULL DEFAULT '{}', next_file integer NOT NULL DEFAULT 0 CHECK (next_file >= 0), sweep_started_at timestamptz, sweep_finished_at timestamptz, last_run_at timestamptz, last_error text, updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.seo_sync_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.seo_sync_state FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.seo_sync_state TO service_role;
CREATE OR REPLACE FUNCTION public.seo_take_inspection_quota(p_property text, p_want integer, p_per_day integer, p_per_minute integer) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE d timestamptz := date_trunc('day', now() AT TIME ZONE 'America/Los_Angeles') AT TIME ZONE 'America/Los_Angeles'; m timestamptz := date_trunc('minute', now()); used_d integer; used_m integer; n integer; BEGIN IF p_property IS NULL OR coalesce(p_want, 0) <= 0 THEN RETURN 0; END IF; INSERT INTO public.seo_inspection_quota (property, window_kind, window_start, used) VALUES (p_property, 'day', d, 0), (p_property, 'minute', m, 0) ON CONFLICT DO NOTHING; SELECT used INTO used_d FROM public.seo_inspection_quota WHERE property = p_property AND window_kind = 'day' AND window_start = d FOR UPDATE; SELECT used INTO used_m FROM public.seo_inspection_quota WHERE property = p_property AND window_kind = 'minute' AND window_start = m FOR UPDATE; n := greatest(0, least(p_want, p_per_day - used_d, p_per_minute - used_m)); IF n > 0 THEN UPDATE public.seo_inspection_quota SET used = used + n WHERE property = p_property AND ((window_kind = 'day' AND window_start = d) OR (window_kind = 'minute' AND window_start = m)); END IF; DELETE FROM public.seo_inspection_quota WHERE window_start < now() - interval '3 days'; RETURN n; END $f$;
REVOKE ALL ON FUNCTION public.seo_take_inspection_quota(text, integer, integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.seo_take_inspection_quota(text, integer, integer, integer) TO service_role;
CREATE OR REPLACE FUNCTION public.seo_index_totals() RETURNS TABLE (kind text, listed bigint, in_sitemap bigint, answers_200 bigint, indexed bigint, not_indexed bigint, not_checked bigint, no_property bigint, scored bigint, average_score numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT s.kind, count(*), count(*) FILTER (WHERE s.in_sitemap), count(*) FILTER (WHERE s.in_sitemap AND s.http_status = 200), count(*) FILTER (WHERE s.in_sitemap AND s.google_status = 'indexed'), count(*) FILTER (WHERE s.in_sitemap AND s.google_status = 'not_indexed'), count(*) FILTER (WHERE s.in_sitemap AND s.property IS NOT NULL AND (s.google_status IS NULL OR s.google_status IN ('unknown', 'error'))), count(*) FILTER (WHERE s.in_sitemap AND s.property IS NULL), count(s.score) FILTER (WHERE s.in_sitemap), round(avg(s.score) FILTER (WHERE s.in_sitemap), 1) FROM public.seo_index_status s GROUP BY s.kind ORDER BY s.kind $f$;
REVOKE ALL ON FUNCTION public.seo_index_totals() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.seo_index_totals() TO service_role;
notify pgrst, 'reload schema';

-- 343_sitemap_indexes.sql
/* Sitemap indexes (round 44): the reads storelib.com's sitemap files make by id, one slice of the id space at a time, a thousand rows after the last id seen (lib/seo/sitemaps.ts readKeyset), and the counts its index makes. Four partial indexes, nothing else: products by id where published (the products files and their count), products by creator and id where published (each creator's product count in the creators files), store_theme_installs by id where published (the websites files and their count), communities by id where published and not deleted (the communities files). With them a file of ten thousand pages is a seek and a short walk at five million rows as at five thousand. A missing table or column is skipped with a notice. No row changes. LOCKS: a plain CREATE INDEX stops writes to its table while it builds, held until the paste ends, so on a large products table run supabase/sql/RUN_SITEMAP_INDEXES_CONCURRENTLY.sql first, one line per Run, or with psql -f; this part then finds each index made and takes no lock. Until it runs the sitemaps read the same rows, more slowly. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 343: products_sitemap_idx skipped, public.products does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'status') THEN RAISE NOTICE 'part 343: products_sitemap_idx skipped, public.products lacks a column it needs'; RETURN; END IF; IF to_regclass('public.products_sitemap_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS products_sitemap_idx ON public.products (id) WHERE status = 'published'; END $do$;
DO $do$ BEGIN IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 343: products_sitemap_creator_idx skipped, public.products does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'status') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'creator_id') THEN RAISE NOTICE 'part 343: products_sitemap_creator_idx skipped, public.products lacks a column it needs'; RETURN; END IF; IF to_regclass('public.products_sitemap_creator_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS products_sitemap_creator_idx ON public.products (creator_id, id) WHERE status = 'published'; END $do$;
DO $do$ BEGIN IF to_regclass('public.store_theme_installs') IS NULL THEN RAISE NOTICE 'part 343: store_theme_installs_sitemap_idx skipped, public.store_theme_installs does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'store_theme_installs' AND column_name = 'status') THEN RAISE NOTICE 'part 343: store_theme_installs_sitemap_idx skipped, public.store_theme_installs lacks a column it needs'; RETURN; END IF; IF to_regclass('public.store_theme_installs_sitemap_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS store_theme_installs_sitemap_idx ON public.store_theme_installs (id) WHERE status = 'published'; END $do$;
DO $do$ BEGIN IF to_regclass('public.communities') IS NULL THEN RAISE NOTICE 'part 343: communities_sitemap_idx skipped, public.communities does not exist here (part 81)'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'communities' AND column_name = 'status') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'communities' AND column_name = 'deleted_at') THEN RAISE NOTICE 'part 343: communities_sitemap_idx skipped, public.communities lacks a column it needs'; RETURN; END IF; IF to_regclass('public.communities_sitemap_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS communities_sitemap_idx ON public.communities (id) WHERE status = 'published' AND deleted_at IS NULL; END $do$;
notify pgrst, 'reload schema';

-- 344_product_import_links.sql
/* Product imports from other platforms (Products > Import from Gumroad). product_import_links keeps which Storelib product each imported product became: the store, the platform (gumroad), the platform's own product id, and the Storelib product. One row per store, platform and product id (unique), so running an import again finds the product it made the first time instead of making a second one. A row is written before the product, as a claim, so two tabs importing the same list make one product; a claim with no product after ten minutes is a run that stopped and may be taken over. Deleting the Storelib product empties product_id (ON DELETE SET NULL), and the product can then be imported again. Deleting the store deletes its rows. No access token, no buyer and no customer data is kept here or anywhere else by the import. Server only (the service role); nobody reads it with a browser key. No rows change. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.product_import_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, source text NOT NULL CHECK (source IN ('gumroad')), external_id text NOT NULL CHECK (char_length(external_id) BETWEEN 1 AND 200), product_id uuid REFERENCES public.products(id) ON DELETE SET NULL, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS product_import_links_source_key ON public.product_import_links (creator_id, source, external_id);
CREATE INDEX IF NOT EXISTS product_import_links_product_idx ON public.product_import_links (product_id) WHERE product_id IS NOT NULL;
ALTER TABLE public.product_import_links ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.product_import_links FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.product_import_links TO service_role;
notify pgrst, 'reload schema';

-- 345_blog_editor.sql
/* The blog editor (/admin/blog, round 45). blog_posts gains a draft copy (draft_content, draft_meta, draft_saved_at): the editor saves into it while a post is live, and the live columns change only on Update. Also author_id, canonical_url, og_image_url, cover_alt, noindex, tags (text[], GIN indexed), and author_name when it is missing. The updated_at trigger is rebuilt to move only when something a reader sees changes, so a view count or a draft save no longer changes a post's modified date or its sitemap lastmod. A published post with no date gets its created_at. New tables: blog_categories (seeded with the blog's eight categories), blog_authors (seeded from the bylines already on posts, which are linked to them), blog_post_revisions (a copy at every manual save and publish, about 50 kept per post), blog_redirects (an old slug and the slug it moved to, followed with a 308) and blog_snippets (reusable blocks). Row level security on every table: the public key reads categories, authors and redirects, and only live posts (published, and the date reached) without their draft columns; revisions and snippets are server only. Safe to run again. */
ALTER TABLE public.blog_posts ADD COLUMN IF NOT EXISTS author_name text, ADD COLUMN IF NOT EXISTS draft_content jsonb, ADD COLUMN IF NOT EXISTS draft_meta jsonb, ADD COLUMN IF NOT EXISTS draft_saved_at timestamptz, ADD COLUMN IF NOT EXISTS canonical_url text, ADD COLUMN IF NOT EXISTS og_image_url text, ADD COLUMN IF NOT EXISTS cover_alt text, ADD COLUMN IF NOT EXISTS noindex boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS tags text[] NOT NULL DEFAULT '{}';
CREATE TABLE IF NOT EXISTS public.blog_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]([a-z0-9-]{0,78}[a-z0-9])?$'), name text NOT NULL UNIQUE CHECK (char_length(name) BETWEEN 1 AND 80), description text NOT NULL DEFAULT '' CHECK (char_length(description) <= 500), sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO public.blog_categories (slug, name, description, sort_order) VALUES ('getting-started', 'Getting Started', 'Everything you need to launch your first digital product store, from choosing what to sell to getting your first sale.', 1), ('creator-tips', 'Creator Tips', 'Practical advice to help you create, market, and sell digital products more effectively.', 2), ('growth', 'Growth', 'Strategies to grow your audience, reach new customers, and scale your creator business.', 3), ('strategy', 'Strategy', 'Business frameworks and pricing tactics for building a sustainable creator income.', 4), ('product-updates', 'Product Updates', 'The latest features, improvements, and news straight from the Storelib team.', 5), ('case-studies', 'Case Studies', 'Real stories from creators who''ve built successful businesses on Storelib.', 6), ('tutorials', 'Tutorials', 'Step-by-step guides to get the most out of every Storelib feature.', 7), ('announcements', 'Announcements', 'Important news and milestones from the Storelib team.', 8) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS public.blog_authors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]([a-z0-9-]{0,78}[a-z0-9])?$'), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 80), role text NOT NULL DEFAULT '' CHECK (char_length(role) <= 80), bio text NOT NULL DEFAULT '' CHECK (char_length(bio) <= 1000), avatar_url text, links jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.blog_posts ADD COLUMN IF NOT EXISTS author_id uuid REFERENCES public.blog_authors(id) ON DELETE SET NULL;
CREATE OR REPLACE FUNCTION public.update_blog_post_updated_at() RETURNS trigger LANGUAGE plpgsql AS $f$ BEGIN IF coalesce(current_setting('storelib.blog_keep_updated_at', true), '') = 'on' THEN NEW.updated_at = OLD.updated_at; RETURN NEW; END IF; IF (to_jsonb(NEW) - ARRAY['views', 'updated_at', 'draft_content', 'draft_meta', 'draft_saved_at']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['views', 'updated_at', 'draft_content', 'draft_meta', 'draft_saved_at']) THEN NEW.updated_at = now(); ELSE NEW.updated_at = OLD.updated_at; END IF; RETURN NEW; END $f$;
DROP TRIGGER IF EXISTS blog_posts_updated_at ON public.blog_posts;
CREATE TRIGGER blog_posts_updated_at BEFORE UPDATE ON public.blog_posts FOR EACH ROW EXECUTE FUNCTION public.update_blog_post_updated_at();
SELECT set_config('storelib.blog_keep_updated_at', 'on', true);
INSERT INTO public.blog_authors (slug, name, role) SELECT DISTINCT ON (s.slug) s.slug, s.name, s.role FROM (SELECT trim(both '-' from regexp_replace(lower(split_part(b.byline, ' - ', 1)), '[^a-z0-9]+', '-', 'g')) AS slug, left(trim(split_part(b.byline, ' - ', 1)), 80) AS name, left(trim(CASE WHEN position(' - ' in b.byline) > 0 THEN substr(b.byline, position(' - ' in b.byline) + 3) ELSE '' END), 80) AS role FROM (SELECT DISTINCT coalesce(nullif(trim(to_jsonb(p) ->> 'author_name'), ''), nullif(trim(to_jsonb(p) ->> 'author'), '')) AS byline FROM public.blog_posts p) b WHERE b.byline IS NOT NULL) s WHERE s.slug ~ '^[a-z0-9]([a-z0-9-]{0,78}[a-z0-9])?$' AND s.name <> '' ORDER BY s.slug, s.role DESC ON CONFLICT (slug) DO NOTHING;
UPDATE public.blog_posts p SET author_id = a.id FROM public.blog_authors a WHERE p.author_id IS NULL AND a.slug = trim(both '-' from regexp_replace(lower(split_part(coalesce(nullif(trim(to_jsonb(p) ->> 'author_name'), ''), nullif(trim(to_jsonb(p) ->> 'author'), ''), ''), ' - ', 1)), '[^a-z0-9]+', '-', 'g'));
UPDATE public.blog_posts SET published_at = coalesce(created_at, now()) WHERE is_published = true AND published_at IS NULL;
SELECT set_config('storelib.blog_keep_updated_at', 'off', true);
CREATE INDEX IF NOT EXISTS blog_posts_tags_idx ON public.blog_posts USING gin (tags);
CREATE INDEX IF NOT EXISTS blog_posts_author_idx ON public.blog_posts (author_id) WHERE author_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS blog_posts_category_idx ON public.blog_posts (category);
CREATE TABLE IF NOT EXISTS public.blog_post_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.blog_posts(id) ON DELETE CASCADE, kind text NOT NULL DEFAULT 'save' CHECK (kind IN ('save', 'publish', 'update', 'unpublish', 'schedule', 'restore')), title text NOT NULL DEFAULT '', content jsonb NOT NULL DEFAULT '[]'::jsonb, meta jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), created_by text);
CREATE INDEX IF NOT EXISTS blog_post_revisions_post_idx ON public.blog_post_revisions (post_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.blog_redirects (from_slug text PRIMARY KEY CHECK (char_length(from_slug) BETWEEN 1 AND 200), to_slug text NOT NULL CHECK (char_length(to_slug) BETWEEN 1 AND 200), post_id uuid REFERENCES public.blog_posts(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), CHECK (from_slug <> to_slug));
CREATE INDEX IF NOT EXISTS blog_redirects_to_idx ON public.blog_redirects (to_slug);
CREATE TABLE IF NOT EXISTS public.blog_snippets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 120), blocks jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.blog_categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.blog_authors ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.blog_post_revisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.blog_redirects ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.blog_snippets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.blog_posts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS blog_categories_public_read ON public.blog_categories;
CREATE POLICY blog_categories_public_read ON public.blog_categories FOR SELECT TO anon, authenticated USING (true);
DROP POLICY IF EXISTS blog_authors_public_read ON public.blog_authors;
CREATE POLICY blog_authors_public_read ON public.blog_authors FOR SELECT TO anon, authenticated USING (true);
DROP POLICY IF EXISTS blog_redirects_public_read ON public.blog_redirects;
CREATE POLICY blog_redirects_public_read ON public.blog_redirects FOR SELECT TO anon, authenticated USING (true);
DROP POLICY IF EXISTS "blog_posts_public_read" ON public.blog_posts;
CREATE POLICY "blog_posts_public_read" ON public.blog_posts FOR SELECT TO anon, authenticated USING (is_published = true AND (published_at IS NULL OR published_at <= now()));
REVOKE ALL ON public.blog_categories, public.blog_authors, public.blog_redirects FROM anon, authenticated;
GRANT SELECT ON public.blog_categories, public.blog_authors, public.blog_redirects TO anon, authenticated;
REVOKE ALL ON public.blog_post_revisions, public.blog_snippets FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.blog_categories, public.blog_authors, public.blog_post_revisions, public.blog_redirects, public.blog_snippets TO service_role;
DO $do$ DECLARE cols text; BEGIN SELECT string_agg(quote_ident(column_name), ', ' ORDER BY ordinal_position) INTO cols FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'blog_posts' AND column_name NOT IN ('draft_content', 'draft_meta', 'draft_saved_at'); REVOKE SELECT ON public.blog_posts FROM anon, authenticated; EXECUTE format('GRANT SELECT (%s) ON public.blog_posts TO anon, authenticated', cols); END $do$;
notify pgrst, 'reload schema';

-- 346_account_attribution.sql
/* Where Storelib's own accounts came from, and the SEO console's crawl checks (round 45, run after 342). account_attribution keeps one row per account made after this deploy: the first and last touch of the visit to storelib.com that ended in the account (the same shape as orders.first_touch and last_touch, part 60: source, referrer host, UTM tags, landing path and host, time) and the AI assistant each names, when its referrer or utm_source names one (ChatGPT, Perplexity, Copilot, Gemini, Claude and others). Written once by the server for a new account; deleting the account deletes its row. No email, no address, no identifier of the device. seo_crawl_reports keeps the last robots.txt and sitemap file check /admin/seo made of the live site. seo_coverage_groups counts Google's own answers by coverage state, and a partial index finds the listed addresses whose live page is not a 200, says noindex or has a canonical elsewhere. Service role only. No rows change. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.account_attribution (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, first_touch jsonb CHECK (first_touch IS NULL OR jsonb_typeof(first_touch) = 'object'), last_touch jsonb CHECK (last_touch IS NULL OR jsonb_typeof(last_touch) = 'object'), first_ai_source text CHECK (first_ai_source IS NULL OR first_ai_source ~ '^[a-z_]{2,20}$'), last_ai_source text CHECK (last_ai_source IS NULL OR last_ai_source ~ '^[a-z_]{2,20}$'), signed_up_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS account_attribution_created_idx ON public.account_attribution (created_at);
CREATE INDEX IF NOT EXISTS account_attribution_ai_idx ON public.account_attribution (created_at) WHERE first_ai_source IS NOT NULL OR last_ai_source IS NOT NULL;
ALTER TABLE public.account_attribution ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.account_attribution FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.account_attribution TO service_role;
CREATE TABLE IF NOT EXISTS public.seo_crawl_reports (report_kind text PRIMARY KEY CHECK (report_kind IN ('robots', 'sitemaps')), report jsonb NOT NULL CHECK (jsonb_typeof(report) = 'object'), checked_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.seo_crawl_reports ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.seo_crawl_reports FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.seo_crawl_reports TO service_role;
DO $do$ BEGIN IF to_regclass('public.seo_index_status') IS NULL THEN RAISE NOTICE 'part 346: seo_coverage_groups and seo_index_status_conflict_idx skipped, run 342_seo_index_status.sql first'; RETURN; END IF; EXECUTE $e$CREATE INDEX IF NOT EXISTS seo_index_status_conflict_idx ON public.seo_index_status (url) WHERE in_sitemap AND scored_at IS NOT NULL AND (http_status IS DISTINCT FROM 200 OR checks @> '[{"id": "indexable", "state": "fail"}]' OR checks @> '[{"id": "canonical", "state": "fail"}]')$e$; EXECUTE $e$CREATE OR REPLACE FUNCTION public.seo_coverage_groups() RETURNS TABLE (google_status text, coverage_state text, addresses bigint, newest_answer timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT s.google_status, coalesce(s.coverage_state, 'Google gave no coverage state'), count(*), max(s.inspected_at) FROM public.seo_index_status s WHERE s.in_sitemap AND s.inspected_at IS NOT NULL AND s.google_status IN ('indexed', 'not_indexed') GROUP BY 1, 2 ORDER BY 3 DESC $f$$e$; EXECUTE 'REVOKE ALL ON FUNCTION public.seo_coverage_groups() FROM PUBLIC, anon, authenticated'; EXECUTE 'GRANT EXECUTE ON FUNCTION public.seo_coverage_groups() TO service_role'; END $do$;
notify pgrst, 'reload schema';

-- 347_profiles_keep_email_verified.sql
/* Only the server marks an email address verified. profiles.email_verified (and email_verified_at) decides whether a sign in may join the guest orders bought with the account's address, and a signed in user could set it on their own profile row with the public key, through the owner update policy, without receiving any code. Now a write from the browser key (the anon and authenticated roles) keeps the old values on an update, and a new row from the browser starts unverified; the server (service role: the email code, Google and Apple sign in, an email change) sets it as before. The trigger is only made when both columns exist. No rows change. Safe to run again. */
CREATE OR REPLACE FUNCTION public.profiles_keep_email_verified() RETURNS trigger LANGUAGE plpgsql AS $f$ BEGIN IF current_user IN ('authenticated', 'anon') THEN IF TG_OP = 'INSERT' THEN NEW.email_verified := false; NEW.email_verified_at := NULL; ELSE NEW.email_verified := OLD.email_verified; NEW.email_verified_at := OLD.email_verified_at; END IF; END IF; RETURN NEW; END $f$;
DO $do$ BEGIN IF to_regclass('public.profiles') IS NULL THEN RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'profiles' AND column_name = 'email_verified') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'profiles' AND column_name = 'email_verified_at') THEN RETURN; END IF; DROP TRIGGER IF EXISTS profiles_keep_email_verified ON public.profiles; CREATE TRIGGER profiles_keep_email_verified BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.profiles_keep_email_verified(); END $do$;
notify pgrst, 'reload schema';

-- 348_site_switch_in_one_step.sql
/* An AI site goes live in one step. A new server only function `switch_site_deployment(site, deployment, fields)`, called by an AI site's Publish (lib/sites/publish.ts): the old live deployment comes down and the new one goes up in one transaction, so a publish that fails part way changes nothing and the site that was live stays live, where before a failed second step could leave the site with no live deployment ("Site not found") until Publish was pressed again. It holds a lock per site while it runs, so two publishes of the same site wait for each other. It refuses a deployment that is not that site's. Only the service role can call it. Changes no existing row. Until it runs, Publish switches in two steps and puts the old version back if the second one fails. Needs the AI site tables (RUN_CREATOR_PAGE_AND_SITES, RUN_SITES_PUBLISHING); without them it is not created. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.site_deployments') IS NULL OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'site_deployments' AND column_name = 'is_live') THEN RAISE NOTICE 'site switch in one step: the AI site tables are not there yet.'; RETURN; END IF; EXECUTE $fn$CREATE OR REPLACE FUNCTION public.switch_site_deployment(p_site uuid, p_deployment uuid, p_fields jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $body$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.site_deployments WHERE id = p_deployment AND site_id = p_site) THEN RAISE EXCEPTION 'switch: this deployment is not this site''s' USING ERRCODE = 'P0002'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('storelib-site-switch:' || p_site::text, 0)); UPDATE public.site_deployments SET is_live = false WHERE site_id = p_site AND is_live AND id <> p_deployment; UPDATE public.site_deployments SET is_live = true, status = 'ready', storage_prefix = COALESCE(p_fields->>'storage_prefix', storage_prefix), file_count = COALESCE((p_fields->>'file_count')::integer, file_count), bytes = COALESCE((p_fields->>'bytes')::bigint, bytes), published_at = COALESCE((p_fields->>'published_at')::timestamptz, now()), finished_at = COALESCE((p_fields->>'finished_at')::timestamptz, now()) WHERE id = p_deployment; RETURN true; END $body$$fn$; REVOKE ALL ON FUNCTION public.switch_site_deployment(uuid, uuid, jsonb) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.switch_site_deployment(uuid, uuid, jsonb) TO service_role; END $do$;
notify pgrst, 'reload schema';

-- 349_buyer_email_trigram_indexes.sql
/* Buyer email lookups (round rel-db). Two trigram indexes for the reads that find a buyer's orders or checkouts by email inside one store: creator_id = X and buyer_email ILIKE the address (the storefront account and order pages, order lookup by email and number, access links, checkout's already owned check, the Email area). The btree on buyer_email and the one on lower(buyer_email) cannot serve ILIKE, so each of those reads walked every order or checkout of the store; a GIN index with gin_trgm_ops serves ILIKE of an exact address. pg_trgm is made where it is available (in the extensions schema when there is one), as part 342 does; without it the part skips with a notice and the reads work as before, without an index. No row changes, no policy or function changes. LOCKS: a plain CREATE INDEX stops writes to orders and commerce_checkouts while it builds and the editor holds that to the end of the paste; on a large database run supabase/sql/RUN_BUYER_EMAIL_TRGM_CONCURRENTLY.sql first, ONE LINE PER RUN or with psql -f (CREATE INDEX CONCURRENTLY cannot run inside a transaction, and the editor runs a paste as one), and this part then finds each index made and builds nothing. Each index is made only when its table and column are there. Safe to run again. */
DO $do$ DECLARE sch text; BEGIN IF to_regclass('public.orders') IS NULL THEN RAISE NOTICE 'part 349: orders_buyer_email_trgm_idx skipped, public.orders does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'buyer_email') THEN RAISE NOTICE 'part 349: orders_buyer_email_trgm_idx skipped, public.orders has no buyer_email'; RETURN; END IF; IF to_regclass('public.orders_buyer_email_trgm_idx') IS NOT NULL THEN RETURN; END IF; SELECT n.nspname INTO sch FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'pg_trgm'; IF sch IS NULL AND EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_trgm') THEN IF to_regnamespace('extensions') IS NOT NULL THEN CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA extensions; sch := 'extensions'; ELSE CREATE EXTENSION IF NOT EXISTS pg_trgm; SELECT n.nspname INTO sch FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'pg_trgm'; END IF; END IF; IF sch IS NULL THEN RAISE NOTICE 'part 349: pg_trgm is not available, orders_buyer_email_trgm_idx skipped: lookups by email work, without an index'; RETURN; END IF; EXECUTE format('CREATE INDEX IF NOT EXISTS orders_buyer_email_trgm_idx ON public.orders USING gin (buyer_email %I.gin_trgm_ops) WHERE buyer_email IS NOT NULL', sch); END $do$;
DO $do$ DECLARE sch text; BEGIN IF to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'part 349: commerce_checkouts_buyer_email_trgm_idx skipped, public.commerce_checkouts does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'commerce_checkouts' AND column_name = 'buyer_email') THEN RAISE NOTICE 'part 349: commerce_checkouts_buyer_email_trgm_idx skipped, public.commerce_checkouts has no buyer_email'; RETURN; END IF; IF to_regclass('public.commerce_checkouts_buyer_email_trgm_idx') IS NOT NULL THEN RETURN; END IF; SELECT n.nspname INTO sch FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'pg_trgm'; IF sch IS NULL AND EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_trgm') THEN IF to_regnamespace('extensions') IS NOT NULL THEN CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA extensions; sch := 'extensions'; ELSE CREATE EXTENSION IF NOT EXISTS pg_trgm; SELECT n.nspname INTO sch FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'pg_trgm'; END IF; END IF; IF sch IS NULL THEN RAISE NOTICE 'part 349: pg_trgm is not available, commerce_checkouts_buyer_email_trgm_idx skipped: lookups by email work, without an index'; RETURN; END IF; EXECUTE format('CREATE INDEX IF NOT EXISTS commerce_checkouts_buyer_email_trgm_idx ON public.commerce_checkouts USING gin (buyer_email %I.gin_trgm_ops) WHERE buyer_email IS NOT NULL', sch); END $do$;
notify pgrst, 'reload schema';

-- 350_platform_ai_visits.sql
/* Visits to storelib.com's own pages from an AI assistant, counted by Storelib (round 46). platform_ai_visits keeps one number per day (UTC), assistant (chatgpt, perplexity, copilot, gemini, claude and the others lib/attribution/ai-sources names) and landing path (Storelib's own public pages only: no query string, no hash, lower case, at most 200 characters). A visit from an assistant to one of those pages, from a visitor who said yes to analytics, adds one through bump_platform_ai_visit, called by /api/track/ai-visit with the service role. No visitor, no address, no user agent, no cookie: a count, never a row per person. Service role only: row level security on, no policy for anyone else, the function executable by the service role alone. No rows change. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.platform_ai_visits (day date NOT NULL, ai_source text NOT NULL CHECK (ai_source ~ '^[a-z_]{2,20}$'), landing_path text NOT NULL CHECK (char_length(landing_path) BETWEEN 1 AND 200 AND landing_path ~ '^/[a-z0-9/_-]*$'), visits bigint NOT NULL DEFAULT 0 CHECK (visits >= 0), PRIMARY KEY (day, ai_source, landing_path));
ALTER TABLE public.platform_ai_visits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.platform_ai_visits FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.platform_ai_visits TO service_role;
CREATE OR REPLACE FUNCTION public.bump_platform_ai_visit(p_source text, p_path text) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path = public AS $f$ INSERT INTO public.platform_ai_visits AS v (day, ai_source, landing_path, visits) VALUES ((now() AT TIME ZONE 'utc')::date, p_source, p_path, 1) ON CONFLICT (day, ai_source, landing_path) DO UPDATE SET visits = v.visits + 1 $f$;
REVOKE ALL ON FUNCTION public.bump_platform_ai_visit(text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.bump_platform_ai_visit(text, text) TO service_role;
notify pgrst, 'reload schema';

-- 352_checkout_attempts.sql
/* Product checkout attempts (reliability PAY-9). checkout_attempts keeps, for one press of Pay on one order (the page's attempt id, the store, the product, the buyer's email and a hash of what is charged: amount, currency, choices), the tokens that order's PaymentIntent carries (access token, session fingerprint, receipt token, the time the terms were agreed) and the PaymentIntent made for it. A second press or a retried request for the same order reads the same tokens back, so Stripe gets the same request under the same idempotency key and answers the first PaymentIntent instead of making a second one; a changed order is a new row and a new PaymentIntent. Rows expire after 24 hours (as Stripe forgets a key) and are deleted by the checkout itself. Until this part runs the checkout works exactly as before. Service role only: row level security on, no policy for anyone else, nothing granted to anon or authenticated. No rows change. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.checkout_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_key text NOT NULL UNIQUE CHECK (char_length(attempt_key) BETWEEN 16 AND 128), creator_id uuid NOT NULL, product_id uuid NOT NULL, buyer_email text NOT NULL, access_token text NOT NULL DEFAULT '', session_fingerprint text NOT NULL, receipt_token text NOT NULL, agreed_at timestamptz NOT NULL, params_hash text NOT NULL, payment_intent_id text, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now() + interval '24 hours'));
CREATE INDEX IF NOT EXISTS checkout_attempts_expires_at_idx ON public.checkout_attempts (expires_at);
ALTER TABLE public.checkout_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.checkout_attempts FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.checkout_attempts TO service_role;
notify pgrst, 'reload schema';

-- 354_builder_configs_private.sql
/* Creator page configs private (round 48, finding R48-6 in docs/reliability/SECURITY.md). Run only after the deploy that moved public reads to the server (round 48): before it, the creator pages, product pages and OnePages read store_builder_configs and product_page_configs with the anon key, and this part closes that door, so run it earlier and those pages draw their default look until the deploy lands. WHY: the anon key is in every page Storelib serves, and the policy the repository's baseline made (store_builder_configs_public_read and product_page_configs_public_read, and the older "Anyone can view published configs" of scripts/010) let it read every row with a published config through the REST API, draft_config and published_config.headerSettings.contactEmail included; row level security cannot hide a column. Production's policies were made by hand, so this part reads them rather than assuming names. WHAT IT DOES, for each of the two tables that exists: 1. drops every permissive SELECT or ALL policy that is not an owner policy, with a notice naming it, its roles and its USING text; an owner policy is one whose USING reads auth.uid() and creator_id and reads no config column (published_config, draft_config, published_at), so a policy that also lets a published row through is dropped. 2. makes sure the owner can still read and write their own rows: <table>_owner_select, _owner_insert, _owner_update and _owner_delete, for the authenticated role, creator_id in the creators rows whose user_id is (select auth.uid()); each is created only when no policy of that name exists. The editor and the dashboard read with the owner's own session, or with the service role after an ownership check (team members), and the service role passes row level security, so nothing the app does needs more. 3. turns row level security on (a no op where it is on) and takes every privilege on the two tables away from anon, so a policy added later by hand cannot open them to the public key again. Changes no rows. Takes a short lock on each table. Safe to run again: a second run finds nothing to drop and every owner policy there. To check before or after: select policyname, roles, cmd, qual from pg_policies where tablename in ('store_builder_configs','product_page_configs'); */
DO $do$ DECLARE t text; r record; dropped int := 0; BEGIN FOREACH t IN ARRAY ARRAY['store_builder_configs', 'product_page_configs'] LOOP IF to_regclass('public.' || t) IS NULL THEN RAISE NOTICE 'part 354: public.% does not exist here, skipped', t; CONTINUE; END IF; FOR r IN SELECT p.policyname, p.roles, p.cmd, p.qual FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = t AND p.permissive = 'PERMISSIVE' AND p.cmd IN ('SELECT', 'ALL') AND NOT (coalesce(p.qual, '') ~ 'auth\.uid\(\)' AND coalesce(p.qual, '') ~ 'creator_id' AND coalesce(p.qual, '') !~ '(published_config|draft_config|published_at)') ORDER BY p.policyname LOOP EXECUTE format('DROP POLICY %I ON public.%I', r.policyname, t); dropped := dropped + 1; RAISE NOTICE 'part 354: dropped policy "%" on % (% for %, using %)', r.policyname, t, r.cmd, r.roles, coalesce(r.qual, 'nothing'); END LOOP; END LOOP; RAISE NOTICE 'part 354: % policies that let more than the owner read dropped', dropped; END $do$;
DO $do$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['store_builder_configs', 'product_page_configs'] LOOP IF to_regclass('public.' || t) IS NULL THEN CONTINUE; END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = t AND policyname = t || '_owner_select') THEN EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = (SELECT auth.uid())))', t || '_owner_select', t); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = t AND policyname = t || '_owner_insert') THEN EXECUTE format('CREATE POLICY %I ON public.%I FOR INSERT TO authenticated WITH CHECK (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = (SELECT auth.uid())))', t || '_owner_insert', t); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = t AND policyname = t || '_owner_update') THEN EXECUTE format('CREATE POLICY %I ON public.%I FOR UPDATE TO authenticated USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = (SELECT auth.uid()))) WITH CHECK (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = (SELECT auth.uid())))', t || '_owner_update', t); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = t AND policyname = t || '_owner_delete') THEN EXECUTE format('CREATE POLICY %I ON public.%I FOR DELETE TO authenticated USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = (SELECT auth.uid())))', t || '_owner_delete', t); END IF; EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('REVOKE ALL ON public.%I FROM anon', t); END LOOP; END $do$;
notify pgrst, 'reload schema';

-- 355_site_blog.sql
/* Creator website blogs (lib/site-blog). Six tables, each keyed by the store (creator_id), so a blog outlives a theme switch: site_blog_settings (the blog's address, previous addresses answered with a 308, title, description, posts per page, search and share details), site_blog_authors, site_blog_categories, site_blog_posts (the LIVE columns visitors read, written only by Publish/Update, and the WORKING copy draft_meta/draft_content every autosave writes; status draft, published or archived, a published post with a date ahead is scheduled and goes live by itself with no job; version for the editor's 409; summary, the opening words the cards show), site_blog_post_revisions (fifty kept per post) and site_blog_redirects (an old post address to the new one). Row level security on every table, four policies each for the store's owner; nothing granted to anon: visitors read through the server, filtered by creator_id, live columns only. Until it runs the Blog screen says it is waiting for this part and every site draws exactly as before. No existing rows change. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.site_blog_settings (creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE, handle text NOT NULL DEFAULT 'news' CHECK (handle ~ '^[a-z0-9][a-z0-9-]{0,62}$'), previous_handles text[] NOT NULL DEFAULT '{}', title text NOT NULL DEFAULT 'Blog' CHECK (char_length(title) <= 120), description text NOT NULL DEFAULT '' CHECK (char_length(description) <= 1000), posts_per_page int NOT NULL DEFAULT 12 CHECK (posts_per_page BETWEEN 1 AND 48), seo_title text, seo_description text, og_image_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.site_blog_authors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, slug text NOT NULL CHECK (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 120), role text, bio text, avatar_url text, links jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (creator_id, slug));
CREATE TABLE IF NOT EXISTS public.site_blog_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, slug text NOT NULL CHECK (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 80), description text NOT NULL DEFAULT '', sort_order int NOT NULL DEFAULT 0, seo_title text, seo_description text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (creator_id, slug));
CREATE TABLE IF NOT EXISTS public.site_blog_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','archived')), slug text NOT NULL CHECK (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' AND char_length(slug) <= 120), title text NOT NULL DEFAULT '', excerpt text NOT NULL DEFAULT '', summary text NOT NULL DEFAULT '', content jsonb NOT NULL DEFAULT '[]', cover_image_url text, cover_alt text, category_id uuid REFERENCES public.site_blog_categories(id) ON DELETE SET NULL, tags text[] NOT NULL DEFAULT '{}', author_id uuid REFERENCES public.site_blog_authors(id) ON DELETE SET NULL, seo_title text, seo_description text, canonical_url text, og_title text, og_description text, og_image_url text, noindex boolean NOT NULL DEFAULT false, featured boolean NOT NULL DEFAULT false, word_count int NOT NULL DEFAULT 0, reading_minutes int NOT NULL DEFAULT 0, published_at timestamptz, first_published_at timestamptz, content_updated_at timestamptz, draft_meta jsonb, draft_content jsonb, draft_saved_at timestamptz, version int NOT NULL DEFAULT 1, created_by uuid, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (creator_id, slug));
CREATE INDEX IF NOT EXISTS site_blog_posts_live_idx ON public.site_blog_posts (creator_id, published_at DESC) WHERE status = 'published';
CREATE INDEX IF NOT EXISTS site_blog_posts_admin_idx ON public.site_blog_posts (creator_id, status, updated_at DESC);
CREATE INDEX IF NOT EXISTS site_blog_posts_category_idx ON public.site_blog_posts (creator_id, category_id);
CREATE INDEX IF NOT EXISTS site_blog_posts_tags_idx ON public.site_blog_posts USING gin (tags);
CREATE TABLE IF NOT EXISTS public.site_blog_post_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.site_blog_posts(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, kind text NOT NULL CHECK (kind IN ('save','publish','update','schedule','unpublish','restore')), meta jsonb NOT NULL, content jsonb NOT NULL, created_by uuid, created_at timestamptz NOT NULL DEFAULT now());
