-- 356_public_snapshots.sql
/* Stored copies of public pages (round 49, lib/edge/public-snapshot.ts). A private Storage bucket, public-snapshots: one JSON object per page of a published website, a OnePage or a community's public page, as a stranger is shown it, plus a small index per site and a record per website host (which site a connected domain is). The proxy serves a copy when the database does not answer, instead of "One moment". Written and read only by the server with the service role, which needs no policy; nothing is granted to anon or authenticated, and the bucket is not public. 4 MB per object, JSON only. Until it runs, every copy write fails quietly and pages answer exactly as before. No rows change. Safe to run again. */
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('public-snapshots', 'public-snapshots', false, 4194304, ARRAY['application/json'])
ON CONFLICT (id) DO UPDATE SET public = false, file_size_limit = 4194304, allowed_mime_types = ARRAY['application/json'];
notify pgrst, 'reload schema';

-- 360_theme_publish_jobs.sql
/* Publish as a job with a deadline (round 51, lib/website-builder/publish-job.ts). One row per press of Publish, named by the editor (its own id, so the same press sent twice is one publish): running, done or failed, with the moment it must have ended by. The editor asks for its row when the answer to its press was lost or slow, instead of spinning. Written and read only by the server with the service role; row level security on with no policy, and nothing granted to anon or authenticated. Until it runs, Publish works exactly as before and a lost answer is asked again. No rows change. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.theme_publish_jobs ( id uuid PRIMARY KEY, install_id uuid NOT NULL REFERENCES public.store_theme_installs(id) ON DELETE CASCADE, creator_id uuid NOT NULL, status text NOT NULL DEFAULT 'running' CHECK (status IN ('running', 'done', 'failed')), error text, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, deadline_at timestamptz NOT NULL DEFAULT (now() + interval '150 seconds') );
CREATE INDEX IF NOT EXISTS idx_theme_publish_jobs_install ON public.theme_publish_jobs (install_id, started_at DESC);
ALTER TABLE public.theme_publish_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.theme_publish_jobs FROM anon, authenticated;
notify pgrst, 'reload schema';

-- 363_membership_livemode.sql
/* Memberships made with Stripe's test keys (round 51, lib/memberships/sync.ts, lib/communities/membership-money.ts payingAt). One new column, memberships.livemode (boolean, empty by default): the membership sync writes false on a subscription Stripe says is in test mode, and the community MRR, paying members and the Analytics money then leave that row out. Empty means a live subscription, as every row was read before. Nothing else changes: no row is rewritten, no rule or policy. Until it runs, memberships read and sync as before. Needs part 75 (memberships); skips itself with a notice without it. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.memberships') IS NULL THEN RAISE NOTICE 'memberships.livemode skipped: public.memberships does not exist here (part 75)'; RETURN; END IF; ALTER TABLE public.memberships ADD COLUMN IF NOT EXISTS livemode boolean; END $do$;
notify pgrst, 'reload schema';

-- 366_deleted_community_notifications.sql
/* A deleted community leaves nobody's bell (round 51, lib/communities/server/community-gone.ts). From now on a community's notifications are deleted the moment it is deleted; this clears the ones left by communities deleted before: their community_notifications rows, and the user_notifications rows that open one of their addresses (its own, below it, with a query, or an address it used to have). Rows of communities that are not deleted are not touched. A table that is not there yet is skipped. Nothing else changes. Safe to run again. */
DO $f$ BEGIN IF to_regclass('public.community_notifications') IS NOT NULL AND to_regclass('public.communities') IS NOT NULL THEN DELETE FROM public.community_notifications n USING public.communities c WHERE n.community_id = c.id AND c.deleted_at IS NOT NULL; END IF; END $f$;
DO $f$ BEGIN IF to_regclass('public.user_notifications') IS NOT NULL AND to_regclass('public.communities') IS NOT NULL THEN DELETE FROM public.user_notifications u USING public.communities c WHERE c.deleted_at IS NOT NULL AND (u.url = '/community/' || c.slug OR u.url LIKE '/community/' || c.slug || '/%' OR u.url LIKE '/community/' || c.slug || '?%'); END IF; END $f$;
DO $f$ BEGIN IF to_regclass('public.user_notifications') IS NOT NULL AND to_regclass('public.community_slug_history') IS NOT NULL THEN DELETE FROM public.user_notifications u USING public.community_slug_history h, public.communities c WHERE h.community_id = c.id AND c.deleted_at IS NOT NULL AND (u.url = '/community/' || h.slug OR u.url LIKE '/community/' || h.slug || '/%' OR u.url LIKE '/community/' || h.slug || '?%'); END IF; END $f$;
notify pgrst, 'reload schema';

-- 353_rls_initplan_and_product_counters.sql
/* Database load, round r48 (read with docs/reliability/IMPLEMENTATION_LOG.md, section r48-db). Two changes, neither changes a row. 1. ROW LEVEL SECURITY READS THE SIGNED IN USER ONCE PER QUERY, NOT ONCE PER ROW. About 170 policies on about 100 tables call auth.uid(), auth.jwt() or auth.role() bare, so Postgres works the call out again for every row it checks (the Supabase advisor's "auth RLS initplan" warning, DB-13 in the audit). Each such call is now written (select auth.uid()), which Postgres works out once per query; the newer policies were already written that way. Every policy keeps its name, command, roles and meaning: ALTER POLICY changes only its USING and WITH CHECK text, and the part reads each policy back and puts it back as it was, with a notice, unless the new text is the old one word for word once each (select auth.x()) is read as auth.x(). Only policies in the public schema (the storage policies belong to part 90). A policy on a table the editor does not own is left as it was, with a notice. 2. A PRODUCT'S VIEW AND SALES COUNTERS NO LONGER MOVE ITS updated_at. increment_product_views and increment_product_sales add one to products.views and products.sales_count, and the updated_at trigger moved updated_at each time, so every counted visit changed the product's modified date and its sitemap lastmod (lib/seo/sitemaps.ts), as part 345 found for blog posts. The trigger set_products_updated_at now calls storelib_products_updated_at(), which keeps updated_at when an update changed only those two counters and moves it for anything else, exactly as before. LOCKS: ALTER POLICY takes a short exclusive lock on each table it changes, held until the paste ends; the whole part takes well under a second on a large database (measured on 400k orders and 1.3M page views), so run it at a quiet moment like any part. Safe to run again: a second run finds nothing to change. */
DO $do$ BEGIN IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 353: public.products does not exist here, its updated_at trigger skipped'; RETURN; END IF; IF (SELECT count(*) FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name IN ('views', 'sales_count', 'updated_at')) < 3 THEN RAISE NOTICE 'part 353: products has no views, sales_count or updated_at column here, its updated_at trigger left as it was'; RETURN; END IF; CREATE OR REPLACE FUNCTION public.storelib_products_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $f$ BEGIN IF (NEW.views IS DISTINCT FROM OLD.views OR NEW.sales_count IS DISTINCT FROM OLD.sales_count) AND (to_jsonb(NEW) - ARRAY['views', 'sales_count', 'updated_at', 'is_on_sale']) = (to_jsonb(OLD) - ARRAY['views', 'sales_count', 'updated_at', 'is_on_sale']) THEN RETURN NEW; END IF; NEW.updated_at = now(); RETURN NEW; END $f$; COMMENT ON FUNCTION public.storelib_products_updated_at() IS 'Part 353: moves products.updated_at on every update except one that changed only the views or sales_count counters.'; IF to_regprocedure('public.update_updated_at_column()') IS NOT NULL AND EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgrelid = 'public.products'::regclass AND t.tgname = 'set_products_updated_at' AND NOT t.tgisinternal AND t.tgfoid = to_regprocedure('public.update_updated_at_column()')) THEN DROP TRIGGER set_products_updated_at ON public.products; CREATE TRIGGER set_products_updated_at BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.storelib_products_updated_at(); END IF; END $do$;
DO $do$ DECLARE r record; nq text; nw text; same boolean; done int := 0; kept int := 0; wrapped constant text := '\( SELECT auth\.(uid|jwt|role|email)\(\) AS (uid|jwt|role|email)\)'; bare constant text := 'auth\.(uid|jwt|role|email)\(\)'; BEGIN FOR r IN SELECT p.tablename, p.policyname, p.qual, p.with_check FROM pg_policies p WHERE p.schemaname = 'public' AND regexp_replace(coalesce(p.qual, '') || ' ' || coalesce(p.with_check, ''), wrapped, '', 'g') ~ bare ORDER BY p.tablename, p.policyname LOOP nq := regexp_replace(regexp_replace(regexp_replace(r.qual, wrapped, chr(1) || '\1' || chr(2), 'g'), bare, '( SELECT auth.\1() AS \1)', 'g'), chr(1) || '(uid|jwt|role|email)' || chr(2), '( SELECT auth.\1() AS \1)', 'g'); nw := regexp_replace(regexp_replace(regexp_replace(r.with_check, wrapped, chr(1) || '\1' || chr(2), 'g'), bare, '( SELECT auth.\1() AS \1)', 'g'), chr(1) || '(uid|jwt|role|email)' || chr(2), '( SELECT auth.\1() AS \1)', 'g'); BEGIN EXECUTE format('ALTER POLICY %I ON public.%I', r.policyname, r.tablename) || CASE WHEN nq IS NULL THEN '' ELSE ' USING (' || nq || ')' END || CASE WHEN nw IS NULL THEN '' ELSE ' WITH CHECK (' || nw || ')' END; SELECT regexp_replace(p.qual, wrapped, 'auth.\1()', 'g') IS NOT DISTINCT FROM regexp_replace(r.qual, wrapped, 'auth.\1()', 'g') AND regexp_replace(p.with_check, wrapped, 'auth.\1()', 'g') IS NOT DISTINCT FROM regexp_replace(r.with_check, wrapped, 'auth.\1()', 'g') AND regexp_replace(coalesce(p.qual, '') || ' ' || coalesce(p.with_check, ''), wrapped, '', 'g') !~ bare INTO same FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = r.tablename AND p.policyname = r.policyname; IF NOT coalesce(same, false) THEN RAISE EXCEPTION 'it read back differently'; END IF; done := done + 1; EXCEPTION WHEN OTHERS THEN kept := kept + 1; RAISE NOTICE 'part 353: policy "%" on % left as it was (%)', r.policyname, r.tablename, SQLERRM; END; END LOOP; RAISE NOTICE 'part 353: % policies now read the signed in user once per query, % left as they were', done, kept; END $do$;
notify pgrst, 'reload schema';

